components.css:
.ds-btn-primary {
  display:inline-flex; align-items:center; justify-content:center; gap:8px;
  height:40px; padding:0 18px; border:0; border-radius:10px;
  background:#C9451F; color:#FFFFFF; font-family:Manrope, system-ui, -apple-system, 'Segoe UI', Roboto, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif;
  font-size:14px; font-weight:650; line-height:1; cursor:pointer;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.16);
  transition:background-color 160ms cubic-bezier(.22,1,.36,1), transform 160ms cubic-bezier(.22,1,.36,1), box-shadow 160ms cubic-bezier(.22,1,.36,1);
}
.ds-btn-primary:hover { background:#B23A15; transform:translateY(-1px); box-shadow:inset 0 1px 0 rgba(255,255,255,.16), 0 10px 22px -12px rgba(201,69,31,.7); }
.ds-btn-primary:active { background:#9C3010; transform:translateY(0); }
.ds-btn-primary:focus-visible { outline:2px solid #C9451F; outline-offset:2px; }

.ds-btn-secondary {
  display:inline-flex; align-items:center; justify-content:center; gap:8px;
  height:40px; padding:0 18px; border:1px solid #D4CABB; border-radius:10px;
  background:#FFFFFF; color:#0B1B2B; font-family:Manrope, system-ui, -apple-system, 'Segoe UI', Roboto, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif;
  font-size:14px; font-weight:650; line-height:1; cursor:pointer;
  transition:background-color 160ms cubic-bezier(.22,1,.36,1), border-color 160ms cubic-bezier(.22,1,.36,1), transform 160ms cubic-bezier(.22,1,.36,1);
}
.ds-btn-secondary:hover { background:#FCFAF6; border-color:#8A8172; transform:translateY(-1px); }

.ds-input {
  width:100%; height:42px; padding:1px 12px; border:0; border-radius:10px;
  background:#FFFFFF; color:#0B1B2B; box-shadow:0 0 0 1px #D4CABB inset;
  font-family:Manrope, system-ui, -apple-system, 'Segoe UI', Roboto, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif; font-size:14px; outline:none;
  transition:box-shadow 160ms cubic-bezier(.22,1,.36,1);
}
.ds-input::placeholder { color:#6B665C; }
.ds-input:hover { box-shadow:0 0 0 1px #8A8172 inset; }
.ds-input:focus { box-shadow:0 0 0 1px #C9451F inset, 0 0 0 3px rgba(201,69,31,.14); }

.ds-card {
  background:#FFFFFF; border:1px solid #E7E1D6; border-radius:14px; padding:20px;
  color:#0B1B2B; font-family:Manrope, system-ui, -apple-system, 'Segoe UI', Roboto, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif; font-size:14px; line-height:1.65;
}
.ds-card h3 { margin:0 0 6px; font-size:16px; font-weight:700; letter-spacing:-.015em; }
.ds-card p { margin:0; color:#4C5661; }
.ds-card--interactive { transition:transform 200ms cubic-bezier(.22,1,.36,1), box-shadow 200ms cubic-bezier(.22,1,.36,1), border-color 200ms cubic-bezier(.22,1,.36,1); }
.ds-card--interactive:hover { transform:translateY(-2px); border-color:#D4CABB; box-shadow:0 2px 4px rgba(11,27,43,.04), 0 18px 40px -20px rgba(11,27,43,.28); }

.ds-chip {
  display:inline-flex; align-items:center; gap:5px; padding:3px 10px;
  border-radius:999px; background:#F1ECE3; color:#4C5661;
  font-family:Manrope, system-ui, -apple-system, 'Segoe UI', Roboto, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif; font-size:12px; font-weight:650; line-height:1.6;
}
.ds-chip--primary { background:#FBECE6; color:#9C3010; }
.ds-chip--success { background:#E7F5EF; color:#0E7C5A; }
.ds-chip--warning { background:#FBF0DF; color:#A15C00; }
.ds-chip--danger { background:#FBEAE8; color:#B3261E; }

.ds-ink {
  position:relative; overflow:hidden; border-radius:16px; padding:32px;
  background:#0B1B2B; color:#FFFFFF; font-family:Manrope, system-ui, -apple-system, 'Segoe UI', Roboto, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif;
}
.ds-ink h1 { margin:12px 0 8px; font-size:34px; font-weight:800; letter-spacing:-.03em; color:#FFFFFF; }
.ds-ink p { margin:0; max-width:56ch; color:rgba(255,255,255,.65); font-size:13.5px; line-height:1.7; }
.ds-ink::after { content:''; position:absolute; right:-80px; top:-100px; width:320px; height:320px; border:1px solid rgba(255,255,255,.1); border-radius:50%; }
